import{_ as a,o,c as t,a0 as r}from"./chunks/framework.BL79I5mR.js";const u=JSON.parse('{"title":"Orquestación de la simulación","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/hidraulica/03-orquestacion-de-la-simulacion.md","filePath":"es/explanation/hidraulica/03-orquestacion-de-la-simulacion.md"}'),l={name:"es/explanation/hidraulica/03-orquestacion-de-la-simulacion.md"};function s(i,e,n,d,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="orquestacion-de-la-simulacion" tabindex="-1">Orquestación de la simulación <a class="header-anchor" href="#orquestacion-de-la-simulacion" aria-label="Permalink to &quot;Orquestación de la simulación&quot;">​</a></h1><h2 id="el-ciclo-de-avance-temporal-global" tabindex="-1">El ciclo de avance temporal global <a class="header-anchor" href="#el-ciclo-de-avance-temporal-global" aria-label="Permalink to &quot;El ciclo de avance temporal global&quot;">​</a></h2><p>El motor es una API de paso único. Cada llamada a <code>SWMMEngine::step()</code> ejecuta exactamente un paso de tránsito (o un paso solo de escorrentía cuando el tránsito está deshabilitado). La secuencia dentro de un paso es (<code>SWMMEngine.cpp:941</code>):</p><ol><li>Calcular el paso de tránsito $dt_{\\mathrm{next}}$. Si la opción de paso variable está habilitada, el paso limitado por Courant es</li></ol><p>$$dt_{\\mathrm{cfl}} = \\texttt{router.getAdaptiveStep}(\\texttt{routing_step},\\ \\texttt{variable_step}),$$</p><p>luego $dt_{\\mathrm{next}} = \\min(\\texttt{routing_step},\\ dt_{\\mathrm{cfl}})$ acotado a la duración restante de la simulación. 2. Guardar el estado hidráulico anterior (<code>ctx.save_state()</code>). 3. Reiniciar los acumuladores de balance de masa del paso. 4. Ejecutar la cadena:</p><ol><li><code>stepRunoff($dt$)</code> — hidrología (siempre);</li><li>si el tránsito está habilitado: <code>stepRouting($dt$)</code> (hidráulica + calidad), <code>updateStatistics($dt$)</code>, <code>updateRoutingMassBalance($dt$)</code>;</li><li><code>computeFinalStorage()</code>.</li><li>Avanzar el reloj de la simulación y publicar las instantáneas de salida.</li></ol><h2 id="relojes-de-escorrentia-y-de-transito" tabindex="-1">Relojes de escorrentía y de tránsito <a class="header-anchor" href="#relojes-de-escorrentia-y-de-transito" aria-label="Permalink to &quot;Relojes de escorrentía y de tránsito&quot;">​</a></h2><p>La hidrología y la hidráulica corren en relojes <em>independientes</em>:</p><ul><li>El <strong>reloj de escorrentía</strong> avanza al paso húmedo (300 s por defecto) o al paso seco (3600 s por defecto), acortado para alinear con los límites de los pluviómetros. <code>stepRunoff</code> ejecuta múltiples subpasos de escorrentía dentro de un paso de tránsito ($\\text{mientras } t_{\\mathrm{runoff}} &lt; t_{\\mathrm{routing}} + dt$).</li><li>El <strong>reloj de tránsito</strong> avanza en $dt$ (el paso de tránsito) en cada llamada a <code>step()</code>.</li></ul><p>Después de los subpasos de escorrentía, el aporte lateral de tiempo húmedo entregado a los nodos se obtiene por <em>interpolación lineal</em> entre las evaluaciones de escorrentía que lo enmarcan: con $f = (t_{\\mathrm{elapsed}} - t_{\\mathrm{runoff,old}}) / (t_{\\mathrm{runoff,new}} - t_{\\mathrm{runoff,old}})$,</p><p>$$Q_{\\mathrm{runoff}} = (1-f),Q_{\\mathrm{runoff}}^{\\mathrm{old}} + f,Q_{\\mathrm{runoff}}^{\\mathrm{new}},$$</p><p>más los aportes por escurrimiento superficial recibido (runon) y por napa freática. Estos se distribuyen en <code>nodes.runoff_inflow</code> / <code>nodes.gw_inflow</code>.</p><h2 id="aportes-laterales" tabindex="-1">Aportes laterales <a class="header-anchor" href="#aportes-laterales" aria-label="Permalink to &quot;Aportes laterales&quot;">​</a></h2><p>En cada paso de tránsito, los aportes laterales se ensamblan a partir de los búferes de fuente descompuestos en el orden legado (<code>assembleLateralInflows</code>, <code>SWMMEngine.cpp:5691</code>):</p><p>$$Q_{\\mathrm{lat}} = Q_{\\mathrm{ext}} + Q_{\\mathrm{dwf}} + Q_{\\mathrm{wet}} + Q_{\\mathrm{gw}} + Q_{\\mathrm{rdii}} + Q_{\\mathrm{iface}} + Q_{\\mathrm{user}} + Q_{\\mathrm{coupling}},$$</p><p>donde los términos son, respectivamente: series de tiempo externas/ingresos, caudal de tiempo seco (DWF), ingreso de tiempo húmedo (escorrentía), ingreso de napa freática, RDII (infiltración/entrada por lluvia), ingreso por archivo de interfaz, ingreso forzado por el usuario e ingreso por acoplamiento 1D–2D.</p><h2 id="el-paso-de-transito" tabindex="-1">El paso de tránsito <a class="header-anchor" href="#el-paso-de-transito" aria-label="Permalink to &quot;El paso de tránsito&quot;">​</a></h2><p><code>Router::step(ctx, dt, evap_rate, non_conduit_fn)</code> (<code>Routing.cpp:308</code>) ejecuta, en orden:</p><ol><li><strong>initNodeFlows</strong> — inicializa el ingreso de cada nodo desde el aporte lateral y la salida desde las pérdidas (evaporación del estanque y exfiltración de Green–Ampt, acotadas conjuntamente por el volumen almacenado); fija el rebalse a partir del exceso de volumen almacenado.</li><li><strong>computeConduitLosses</strong> — tasas de pérdida de los conductos por evaporación (secciones abiertas) y filtración. Para DYNWAVE esto se recalcula en su lugar en cada iteración de Picard dentro del solver.</li><li><strong>setAllOutfallDepths</strong> — fija los niveles de agua de borde de los emisarios (Sección 13).</li><li><strong>Despacho del solver</strong> — KINWAVE, DYNWAVE, FV o STEADY.</li><li><strong>computeDividerFlows</strong> — aplica la lógica de divisores de flujo.</li><li><strong>updateLinkStates</strong> — recalcula las cargas de los nodos $H = z_{\\mathrm{inv}} + d$.</li></ol><p>Dentro del solver de onda dinámica, la función de retorno de no-conducto calcula los caudales de bombas/orificios/vertederos/descargas dentro de la iteración de Picard, en orden de índice de enlace, con distribución inmediata en los acumuladores de ingreso/salida de los nodos.</p>',21)])])}const h=a(l,[["render",s]]);export{u as __pageData,h as default};
